  'holdall': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.holdall\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Hold-All Domination\ndescription: Teams capture boxes as in Domination, but a team scores only while it holds every box at once.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  tick_s:          { type: int, min: 1, max: 600,   default: 10,   label: "Seconds per scoring tick while one team holds every box" }\n  points_per_tick: { type: int, min: 1, max: 1000,  default: 1,    label: "Points per tick" }\n  min_zones:       { type: int, min: 1, max: 64,    default: 2,    label: "Boxes in play before anyone can score" }\ni18n:\n  pt:\n    name: Domínio Total\n    description: As equipas capturam caixas como no Domínio, mas uma equipa só pontua enquanto tiver todas as caixas ao mesmo tempo.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      tick_s: Segundos por ponto enquanto uma equipa tem todas as caixas\n      points_per_tick: Pontos por intervalo\n      min_zones: Caixas em jogo antes de alguém poder pontuar\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hold-All Domination, on each box: a team captures the box by holding its\n-- input, as in Domination. The box does not score by itself: the field\n-- controller\'s field.lua scores a team only while it holds every box.\n\nlocal s = state.node { owner = nil }\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  cap("team_display"):show(team)\n  audio.play("captured")\nend\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console: a team, or none to free the box.\non("cmd.set_owner", function(e)\n  if e.team == s.owner then\n    return\n  end\n  if e.team == nil or e.team == "" or e.team == "none" then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n  else\n    capture(e.team)\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Hold-All Domination, on the field controller: while one team holds every\n-- zone box (and at least params.min_zones of them are in play), it scores\n-- params.points_per_tick every params.tick_s seconds. Box owners come from\n-- the boxes\' STATE reports, which can arrive a little after the capture\n-- event, so the check also runs every second.\n\nlocal fs = state.field { holder = nil }\nlocal tick\n\nlocal function zone_ids()\n  local ids = {}\n  for _, n in ipairs(field.nodes("zone")) do\n    ids[#ids + 1] = n.id\n  end\n  return ids\nend\n\nlocal function check()\n  local ids = zone_ids()\n  local team = nil\n  if #ids >= params.min_zones then\n    team = field.common_owner(ids)\n  end\n  if team == fs.holder then\n    return\n  end\n  if fs.holder ~= nil then\n    cancel(tick)\n    tick = nil\n    emit("holdall.scoring_stop", { team = fs.holder })\n  end\n  fs.holder = team\n  if team ~= nil then\n    emit("holdall.scoring_start", { team = team })\n    -- The first points come one full tick after the last box fell.\n    tick = every(params.tick_s, function()\n      score.add(team, params.points_per_tick, "holdall")\n    end)\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
  },
  'kill_confirmed': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.kill_confirmed\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Kill Confirmed\ndescription: >-\n  Players carry signed NFC tags. A team presses its button at the station and scans the tags it\n  collected: an enemy\'s tag confirms the kill (points for the team, a penalty for the tag\'s team), a\n  teammate\'s tag denies it. Forged tags and tags from another game are refused.\nroles:\n  station: { requires: [nfc, team_input], optional: [display] }\nparams:\n  confirm_points: { type: int, min: 0, max: 100, default: 1, label: "Points for a confirmed kill" }\n  penalty_points: { type: int, min: 0, max: 100, default: 1, label: "Points the killed player\'s team loses" }\n  turn_in_s:      { type: int, min: 3, max: 120, default: 20, label: "Seconds to scan tags after pressing the team button" }\n  retag_after_s:  { type: int, min: 1, max: 3600, default: 60, label: "Seconds before the same player\'s tag counts again" }\ni18n:\n  pt:\n    name: Baixa Confirmada\n    description: >-\n      Cada participante leva uma etiqueta NFC assinada. Uma equipa carrega no seu botão na estação e lê as\n      etiquetas que recolheu: a etiqueta de alguém da equipa adversária confirma a baixa (pontos para a\n      equipa e penalização para a equipa da etiqueta); a de alguém da própria equipa nega-a. Etiquetas\n      falsificadas ou de outro jogo são recusadas.\n    params:\n      confirm_points: Pontos por baixa confirmada\n      penalty_points: Pontos que perde a equipa de quem foi abatido\n      turn_in_s: Segundos para ler etiquetas depois de carregar no botão da equipa\n      retag_after_s: Segundos até a etiqueta da mesma pessoa voltar a contar\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Kill Confirmed: players carry signed NFC tags (protocol/nfc-tag.md). A team\n-- presses its button at the station, then scans the tags it collected within\n-- turn_in_s seconds (each scan keeps the station open). An enemy\'s tag\n-- confirms the kill: confirm_points for the team, penalty_points off the\n-- tag\'s team. A teammate\'s tag denies the kill: no points. The same player\'s\n-- tag counts again only after retag_after_s. Forged tags, tags from another\n-- game and tags without a team are refused; the shell checks the signature\n-- with the game key and says why in nfc.tag\'s reason.\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\n\nlocal open_team -- the team turning in tags\nlocal closes_at = 0\nlocal closer\nlocal counted = {} -- player -> game time when their tag last counted\nlocal message, failed, fade\n\nlocal function show()\n  local data = { message = message, error = failed }\n  if open_team then\n    data.team = open_team\n    data.left = math.max(0, math.ceil(closes_at - game.time()))\n  end\n  ui.screen("tags", data)\nend\n\n-- A message under the station\'s state, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n    fade = nil\n  end\n  if text then\n    fade = after(4, function()\n      fade = nil\n      message, failed = nil, false\n      show()\n    end)\n  end\nend\n\nlocal function close()\n  open_team, closer = nil, nil\n  say(nil, false)\nend\n\nlocal function open(team)\n  open_team = team\n  closes_at = game.time() + params.turn_in_s\n  if closer then\n    cancel(closer)\n  end\n  closer = after(params.turn_in_s, close)\nend\n\non("game.start", show)\n\non("team_input.press", function(e)\n  open(e.team)\n  say("Scan your tags", false)\nend)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("kill confirmed: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  if open_team == nil then\n    return say("Press your team\'s button first", true)\n  end\n  if e.team == nil then\n    return say("This tag has no team", true)\n  end\n  local last = counted[e.player]\n  if last and game.time() - last < params.retag_after_s then\n    return say("Tag already counted", true)\n  end\n  counted[e.player] = game.time()\n  open(open_team)\n  if e.team == open_team then\n    emit("kill.denied", { team = open_team, player = e.player, owner = e.team })\n    say("Kill denied: " .. e.player, false)\n  else\n    emit("kill.confirmed", { team = open_team, player = e.player, owner = e.team })\n    score.add(open_team, params.confirm_points, "kill")\n    score.add(e.team, -params.penalty_points, "killed")\n    say("Kill confirmed: " .. e.player, false)\n  end\nend)\n\n-- The time left to scan, once a second while the station is open.\nevery(1, function()\n  if open_team then\n    show()\n  end\nend)\n',
    'assets/screens/tags.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The Kill Confirmed station. Data: team (the team turning in tags, while the\n# station is open), left (seconds left to scan), message, error.\ntemplate: tags\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: KILL CONFIRMED\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{!team}" }\n      - type: label\n        text: "{team|upper}: SCAN TAGS"\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{team}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Press your button\n    style: { font_size: 28, visible: "{!team}" }\n  - type: label\n    text: then scan the tags\n    style: { font_size: 20, color: muted, visible: "{!team}" }\n  - type: label\n    text: "{left}"\n    style: { font_size: 48, color: team, visible: "{team}" }\n  - type: progress_bar\n    value: "{left / params.turn_in_s}"\n    style: { width: 240, height: 8, color: team, visible: "{team}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "Enemy tag: confirmed. Team tag: denied."\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'laststand': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.laststand\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Last Stand\ndescription: The defenders start with every zone. Once they are down to their last zone, a countdown to defeat runs until they retake another one.\nroles:\n  zone: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms: { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  attackers:       { type: team, default: red, label: "Attackers (win when the defenders fall)" }\n  defenders:       { type: team, default: blue, label: "Defenders (start with every zone)" }\n  countdown_s:     { type: int, min: 10, max: 3600, default: 120, label: "Countdown to defeat (s)" }\n  last_zones:      { type: int, min: 0, max: 63, default: 1, label: "The countdown runs while the defenders hold this many zones or fewer" }\n  min_zones:       { type: int, min: 1, max: 64, default: 2, label: "Zones in play before the countdown can run" }\n  reset:           { type: bool, default: true, label: "The countdown starts over after a retake (otherwise it carries on where it stopped)" }\n  end_game:        { type: bool, default: true, label: "End the game when the defenders fall" }\ni18n:\n  pt:\n    name: Último Elemento\n    description: Os defensores começam com todas as zonas. Quando ficam reduzidos à última zona, corre uma contagem para a derrota até reconquistarem outra.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      attackers: Atacantes (ganham quando os defensores caem)\n      defenders: Defensores (começam com todas as zonas)\n      countdown_s: Contagem para a derrota (s)\n      last_zones: A contagem corre enquanto os defensores tiverem este número de zonas ou menos\n      min_zones: Zonas em jogo antes de a contagem poder correr\n      reset: A contagem recomeça do início após uma reconquista (senão continua de onde parou)\n      end_game: Terminar o jogo quando os defensores caem\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Last Stand, on each zone box: the defenders hold the box when the game\n-- starts; any team captures it by holding its input. The field controller\'s\n-- field.lua counts the defenders\' zones and runs the countdown to defeat.\n\nlocal s = state.node { owner = nil }\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  cap("team_display"):show(team)\n  audio.play("captured")\nend\n\non("game.start", function()\n  if s.owner == nil then\n    capture(params.defenders)\n  end\nend)\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console: a team, or none to free the box.\non("cmd.set_owner", function(e)\n  if e.team == s.owner then\n    return\n  end\n  if e.team == nil or e.team == "" or e.team == "none" then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n  else\n    capture(e.team)\n  end\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Last Stand, on the field controller. Once the defence is set up (the\n-- defenders have held more than params.last_zones zones, or 30 s have\n-- passed: box owners come from STATE reports, which can lag), a countdown of\n-- params.countdown_s seconds runs whenever they hold params.last_zones\n-- zones or fewer. Retaking a zone stops it; it starts over (params.reset)\n-- or carries on where it stopped. When it runs out the defenders are\n-- defeated, and with params.end_game the attackers win the game.\n\nlocal fs = state.field { held = 0, countdown = false, defeated = false }\nlocal ready = false -- the defence is set up\nlocal timer -- the defeat timer, while the countdown runs\nlocal left = params.countdown_s -- seconds the next countdown starts from\nlocal deadline = 0\n\nlocal function defeat()\n  timer = nil\n  fs.countdown = false\n  fs.defeated = true\n  emit("laststand.defeated", { team = params.defenders })\n  if params.end_game then\n    game.win(params.attackers)\n  end\nend\n\nlocal function check()\n  if fs.defeated then\n    return\n  end\n  local zones = field.nodes("zone")\n  local held = 0\n  for _, n in ipairs(zones) do\n    if field.owner(n.id) == params.defenders then\n      held = held + 1\n    end\n  end\n  if fs.held ~= held then\n    fs.held = held -- state.field changes reach the console, so write only changes\n  end\n  if held > params.last_zones or game.time() >= 30 then\n    ready = true\n  end\n  local danger = ready and #zones >= params.min_zones and held <= params.last_zones\n  if danger and timer == nil then\n    deadline = game.time() + left\n    timer = after(left, defeat)\n    fs.countdown = true\n    emit("laststand.countdown_start", { team = params.defenders, duration_s = math.ceil(left) })\n  elseif not danger and timer ~= nil then\n    cancel(timer)\n    timer = nil\n    fs.countdown = false\n    local remaining = deadline - game.time()\n    emit(\n      "laststand.countdown_cancel",\n      { team = params.defenders, duration_s = math.ceil(remaining) }\n    )\n    left = params.reset and params.countdown_s or math.max(remaining, 0.1)\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
  },
  'master_satellites': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.master_satellites\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nname: Master and Satellites\ndescription: >-\n  Teams capture a master box and its satellites as in Domination. Only the master scores, and the\n  satellites its holder also holds raise its points; when the master changes hands, every satellite goes\n  back to neutral.\nroles:\n  master:    { requires: [team_input], optional: [team_display, audio, display] }\n  satellite: { requires: [team_input], optional: [team_display, audio, display] }\nparams:\n  capture_hold_ms:     { type: int, min: 0, max: 60000, default: 3000, label: "Hold time to capture (ms)" }\n  tick_s:              { type: int, min: 1, max: 600,   default: 10,   label: "Seconds per scoring tick while a team holds the master" }\n  points_per_tick:     { type: int, min: 1, max: 1000,  default: 2,    label: "Points per tick for the master alone" }\n  satellite_bonus_pct: { type: int, min: 0, max: 1000,  default: 50,   label: "Bonus per satellite held, in % of the master\'s points (rounded down)" }\n  min_satellites:      { type: int, min: 0, max: 63,    default: 0,    label: "Satellites the master\'s holder needs before the master scores" }\ni18n:\n  pt:\n    name: Mestre e Satélites\n    description: >-\n      As equipas capturam uma caixa mestre e os seus satélites como no Domínio. Só a mestre pontua, e os\n      satélites que a mesma equipa tiver aumentam os seus pontos; quando a mestre muda de mãos, todos os\n      satélites voltam a ficar neutros.\n    params:\n      capture_hold_ms: Tempo a premir para capturar (ms)\n      tick_s: Segundos por intervalo enquanto uma equipa tem a mestre\n      points_per_tick: Pontos por intervalo só pela mestre\n      satellite_bonus_pct: Bónus por satélite, em % dos pontos da mestre (arredondado para baixo)\n      min_satellites: Satélites de que a equipa da mestre precisa antes de a mestre pontuar\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Master and Satellites, on each box (the master and the satellites run the\n-- same script): a team captures the box by holding its input, as in\n-- Domination. Boxes do not score: the field controller\'s field.lua scores the\n-- master\'s holder, with a bonus for the satellites it holds too, and frees\n-- every satellite when the master changes hands. It also tells the master box\n-- how many satellites its holder has (the mode command "status"), so the\n-- master shows them; a box that was never told is a satellite, or a box\n-- picked from its own preset list, and shows only who holds it.\n-- Screens (assets/screens/): standby, captured, master_status; final_score at\n-- the end (the Field Box\'s built-in screen).\n\nlocal s = state.node { owner = nil, since = 0 }\nlocal master = nil -- the last status from the controller: { held, of, points }\n\nlocal function show()\n  if s.owner == nil then\n    ui.screen("standby", {})\n  elseif master then\n    ui.screen("master_status", {\n      team = s.owner,\n      since = s.since,\n      held = master.held,\n      of = master.of,\n      points = master.points,\n    })\n  else\n    ui.screen("captured", { team = s.owner, since = s.since })\n  end\nend\n\nlocal function capture(team, squad)\n  emit("zone.captured", { team = team, squad = squad, previous_team = s.owner })\n  s.owner = team\n  s.since = math.floor(game.time())\n  cap("team_display"):show(team)\n  audio.play("captured")\n  if master then\n    -- A new holder of the master starts with no satellites (they are freed);\n    -- the controller\'s next status confirms it.\n    master.held, master.points = 0, params.points_per_tick\n  end\n  show()\nend\n\non("game.start", show)\n\non("team_input.hold", function(e)\n  if e.team ~= s.owner and e.ms >= params.capture_hold_ms then\n    capture(e.team, e.squad)\n  end\nend)\n\n-- The GM\'s owner override from the console, and the controller freeing the\n-- satellites: a team, or none to free the box (a free box stays as it is).\non("cmd.set_owner", function(e)\n  local free = e.team == nil or e.team == "" or e.team == "none"\n  if e.team == s.owner or (free and s.owner == nil) then\n    return\n  end\n  if free then\n    emit("zone.neutralized", { previous_team = s.owner })\n    s.owner = nil\n    cap("team_display"):show("none")\n    show()\n  else\n    capture(e.team)\n  end\nend)\n\n-- From field.lua, to the master box only: its holder\'s satellites and points per tick.\non("cmd.mode", function(e)\n  if e.name ~= "status" or e.team ~= s.owner then\n    return\n  end\n  master = {\n    held = math.tointeger(e.held) or 0,\n    of = math.tointeger(e.of) or 0,\n    points = math.tointeger(e.points) or 0,\n  }\n  show()\nend)\n\non("game.end", function()\n  ui.screen("final_score", { owner = s.owner })\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Master and Satellites, on the field controller: while a team holds the\n-- master box, it scores every params.tick_s seconds (the first points one\n-- full tick after the capture): params.points_per_tick, plus\n-- params.satellite_bonus_pct % of that for each satellite it holds too,\n-- rounded down (score.add takes whole points), and nothing while it holds\n-- fewer than params.min_satellites. When the master leaves a team\'s hands\n-- (to another team, or freed by the GM), every satellite is freed. Box owners\n-- come from the boxes\' STATE reports, which can arrive a little after the\n-- capture event, so the check also runs every second. A satellite that\n-- rebooted is freed at the next change of the master, as on the field.\n-- With more than one master box, the first one (the lowest node id) counts.\n\nlocal fs = state.field { master = nil, held = 0 }\nlocal tick\nlocal told -- the last status sent to the master box\n\nlocal function master_id()\n  local m = field.nodes("master")[1]\n  return m and m.id\nend\n\nlocal function satellites_of(team)\n  local held, of = 0, 0\n  for _, n in ipairs(field.nodes("satellite")) do\n    of = of + 1\n    if team ~= nil and field.owner(n.id) == team then\n      held = held + 1\n    end\n  end\n  return held, of\nend\n\nlocal function points(held)\n  if held < params.min_satellites then\n    return 0\n  end\n  return params.points_per_tick + params.points_per_tick * held * params.satellite_bonus_pct // 100\nend\n\nlocal function free_satellites()\n  for _, n in ipairs(field.nodes("satellite")) do\n    field.send(n.id, "set_owner", { team = "none" })\n  end\nend\n\nlocal function check()\n  local id = master_id()\n  local owner = id and field.owner(id)\n  if owner ~= fs.master then\n    if tick then\n      cancel(tick)\n      tick = nil\n    end\n    if fs.master ~= nil then\n      free_satellites()\n    end\n    fs.master = owner\n    told = nil\n    if owner ~= nil then\n      tick = every(params.tick_s, function()\n        local amount = points(satellites_of(owner))\n        if amount > 0 then\n          score.add(owner, amount, "master")\n        end\n      end)\n    end\n  end\n  local held, of = satellites_of(owner)\n  if fs.held ~= held then\n    fs.held = held -- state.field changes reach the console, so write only changes\n  end\n  if owner ~= nil then\n    local status = owner .. " " .. held .. " " .. of .. " " .. points(held)\n    if status ~= told then\n      told = status\n      field.send(\n        id,\n        "mode",\n        { name = "status", team = owner, held = held, of = of, points = points(held) }\n      )\n    end\n  end\nend\n\non("zone.captured", check)\non("zone.neutralized", check)\nevery(1, check)\n',
    'assets/screens/captured.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds a satellite (or a box with no controller). Data: team, since\n# (game time of the capture, in seconds). Boxes do not score: the master does.\ntemplate: captured\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: ZONE HELD\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "held since {since|clock}"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Hold your button to take it over\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/master_status.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A team holds the master. Data: team, since (game time of the capture, in\n# seconds), held and of (the satellites the team holds, of all of them) and\n# points (the master\'s points per tick with that bonus), from the controller.\ntemplate: master_status\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: team }\n    children:\n      - type: label\n        text: MASTER HELD\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{team|upper}"\n    style: { font_size: 48, color: team }\n  - type: label\n    text: "{held} of {of} satellites"\n    style: { font_size: 20 }\n  - type: label\n    text: "{points} points every {params.tick_s} s"\n    style: { font_size: 20, color: "{points > 0 && \'white\' || \'danger\'}" }\n  - type: label\n    text: "held since {since|clock}"\n    style: { font_size: 14, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Hold your button to take it over\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
    'assets/screens/standby.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# Nobody holds the box (a master or a satellite). No data; the hold time comes\n# from the game\'s parameters.\ntemplate: standby\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: panel }\n    children:\n      - type: label\n        text: ZONE\n        style: { font_size: 20, width: fill, align: center }\n  - type: spacer\n    height: fill\n  - type: label\n    text: HOLD TO CAPTURE\n    style: { font_size: 28, color: accent }\n  - type: label\n    text: "Hold your button for {params.capture_hold_ms / 1000} s"\n    style: { font_size: 20, color: muted }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Nobody holds this zone\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'medic': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.medic\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\n# A role package: added to any game (org.atalaia.domination+org.atalaia.medic), its role\n# brings medic kits to the field, and a node given that role runs this script alone.\nkind: role\nname: Medic Kit\ndescription: >-\n  A medic kit next to any game. A hit player scans their signed NFC tag and holds a button for a time\n  the organisers set, to be healed; letting go early cancels. The kit has a number of heals and shows\n  how many are left; each player can be healed a limited number of times per game, at every kit, and the\n  GM and the players see every heal. Forged tags, tags from another game and players of a team the kit\n  does not serve are refused, and the screen says why.\nroles:\n  medic: { requires: [nfc, team_input], optional: [display, audio] }\nparams:\n  heal_hold_s:          { type: int, min: 1, max: 120, default: 10, label: "Seconds a player holds the button to be healed" }\n  charges:              { type: int, min: 1, max: 999, default: 5, label: "Heals in the kit" }\n  max_heals_per_player: { type: int, min: 0, max: 100, default: 2, label: "Heals per player in the game, at every kit (0: no limit)" }\n  cooldown_s:           { type: int, min: 0, max: 3600, default: 0, label: "Seconds a player waits between two heals (0: no wait)" }\n  team:                 { type: team, optional: true, label: "Team the kit serves (empty: every team)" }\n  lang:                 { type: string, default: pt, max: 2, label: "Language of the kit\'s screen: pt or en" }\ncommands:\n  refill: { roles: [medic], label: "Refill the kit" }\ni18n:\n  pt:\n    name: Ligaduras\n    description: >-\n      Um kit de primeiros socorros ao lado de qualquer jogo. A pessoa atingida lê a sua etiqueta NFC\n      assinada e mantém premido um botão durante o tempo que a organização definir, para receber o\n      tratamento; largar antes do tempo cancela. O kit tem um número de ligaduras e mostra quantas restam;\n      cada pessoa pode receber um número limitado de tratamentos por jogo, em todos os kits, e a\n      organização e quem joga veem cada tratamento. Etiquetas falsificadas ou de outro jogo, e pessoas de\n      uma equipa que o kit não serve, são recusadas, e o ecrã diz porquê.\n    params:\n      heal_hold_s: Segundos a premir o botão para receber o tratamento\n      charges: Ligaduras no kit\n      max_heals_per_player: "Tratamentos por pessoa no jogo, em todos os kits (0: sem limite)"\n      cooldown_s: "Segundos de espera entre dois tratamentos da mesma pessoa (0: sem espera)"\n      team: "Equipa que o kit serve (vazio: todas)"\n      lang: "Língua do ecrã do kit: pt ou en"\n    commands:\n      refill: Repor as ligaduras\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Medic Kit (Ligaduras): a hit player scans their signed NFC tag\n-- (protocol/nfc-tag.md), then holds a button for params.heal_hold_s seconds\n-- to be healed; letting go early cancels the heal. The kit holds\n-- params.charges heals and shows how many are left. A player gets at most\n-- params.max_heals_per_player heals in the game (0: no limit), and waits\n-- params.cooldown_s between two of them. With params.team the kit serves\n-- that team only. Every refusal says why on the screen.\n--\n-- A role package (modes/README.md): in a field game the kit\'s node runs this\n-- script alone, next to any main mode. The controller\'s field.lua counts the\n-- heals of every kit and tells the kits ("heals" mode command), so a limit\n-- holds across kits; a kit out of its reach goes on with its own count and\n-- what it was told. The GM refills a kit from the console ("refill").\n\nlocal HOLD_STEP_MS = 250 -- shells send team_input.hold this often (modes/README.md)\nlocal SCAN_WINDOW_S = 15 -- after a scan, the hold must start within this time\nlocal SHOW_S = 4 -- a result stays on the screen this long\n\nlocal tag_refusals = {\n  mac = "mac", -- forged: signed with another key\n  game = "game", -- a tag from another game\n  no_game = "no_game", -- this kit is not in a controller\'s game\n  team = "team", -- a team this game does not have\n}\n\n-- Why a tag or a hold was refused, in the kit\'s language (params.lang).\nlocal reasons = {\n  pt = {\n    mac = "Etiqueta falsificada",\n    game = "Etiqueta de outro jogo",\n    no_game = "Este kit não está num jogo",\n    team = "Equipa desconhecida",\n    not_tag = "Não é uma etiqueta do jogo",\n    wrong_team = "Este kit é de outra equipa",\n    limit = "Chegaste ao limite de tratamentos",\n    cooldown = "Espera %d s",\n    cancelled = "Largaste antes do tempo: lê a etiqueta outra vez",\n    scan_first = "Lê primeiro a tua etiqueta",\n  },\n  en = {\n    mac = "Forged tag",\n    game = "Tag from another game",\n    no_game = "This kit is not in a game",\n    team = "Unknown team",\n    not_tag = "Not a game tag",\n    wrong_team = "This kit is for another team",\n    limit = "You have had all your heals",\n    cooldown = "Wait %d s",\n    cancelled = "Let go too early: scan again",\n    scan_first = "Scan your tag first",\n  },\n}\nlocal texts = reasons[params.lang] or reasons.pt\n\nlocal s = state.node { charges = params.charges }\nlocal used = {} -- player -> heals in this game: this kit\'s, and those it was told about\nlocal last = {} -- player -> game time (s) of their last heal\nlocal pending -- after a valid scan: { player, team, base } until the heal or a refusal\nlocal window -- the timer that ends the scan\'s wait for a hold\nlocal back -- the timer that brings the idle screen back\n\nlocal function idle()\n  if back then\n    cancel(back)\n    back = nil\n  end\n  if s.charges <= 0 then\n    ui.screen("medic_empty", { team = params.team })\n  else\n    ui.screen("medic_idle", { remaining = s.charges, team = params.team })\n  end\nend\n\n-- A result screen, then the idle screen again after SHOW_S.\nlocal function show(name, data)\n  if back then\n    cancel(back)\n  end\n  ui.screen(name, data)\n  back = after(SHOW_S, function()\n    back = nil\n    idle()\n  end)\nend\n\nlocal function forget()\n  pending = nil\n  if window then\n    cancel(window)\n    window = nil\n  end\nend\n\nlocal function refuse(reason, data)\n  forget()\n  data = data or {}\n  data.reason = reason\n  data.message = string.format(texts[reason], data.wait_s or 0)\n  data.remaining = s.charges\n  log("medic: refused (" .. reason .. ")" .. (data.player and (" for " .. data.player) or ""))\n  show("medic_refused", data)\nend\n\nlocal function heals_of(player)\n  return used[player] or 0\nend\n\nlocal function heal()\n  local p = pending\n  forget()\n  s.charges = s.charges - 1\n  used[p.player] = heals_of(p.player) + 1\n  last[p.player] = game.time()\n  audio.play("healed")\n  emit("medic.heal", {\n    team = p.team,\n    player = p.player,\n    remaining = s.charges,\n    player_heals_used = used[p.player],\n  })\n  show("medic_healed", {\n    player = p.player,\n    team = p.team,\n    remaining = s.charges,\n    used = used[p.player],\n    max = params.max_heals_per_player,\n  })\n  if s.charges <= 0 then\n    emit("medic.empty", { team = params.team })\n  end\nend\n\nlocal function hold_screen(progress)\n  if back then\n    cancel(back)\n    back = nil\n  end\n  ui.screen("medic_hold", {\n    player = pending.player,\n    team = pending.team,\n    progress = progress,\n    left = math.max(0, math.ceil(params.heal_hold_s * (1 - progress))),\n    remaining = s.charges,\n  })\nend\n\non("game.start", idle)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("medic: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    -- unsigned, format and version: not a player tag of this system\n    return refuse(tag_refusals[e.reason] or "not_tag")\n  end\n  local who = { player = e.player, team = e.team }\n  if params.team and e.team ~= params.team then\n    return refuse("wrong_team", who)\n  end\n  if s.charges <= 0 then\n    forget()\n    return idle()\n  end\n  local max = params.max_heals_per_player\n  if max > 0 and heals_of(e.player) >= max then\n    who.used, who.max = heals_of(e.player), max\n    return refuse("limit", who)\n  end\n  local t = last[e.player]\n  if params.cooldown_s > 0 and t and game.time() - t < params.cooldown_s then\n    who.wait_s = math.ceil(params.cooldown_s - (game.time() - t))\n    return refuse("cooldown", who)\n  end\n  forget()\n  pending = { player = e.player, team = e.team }\n  window = after(SCAN_WINDOW_S, function()\n    window = nil\n    pending = nil\n    idle()\n  end)\n  hold_screen(0)\nend)\n\n-- A press after the scan starts the hold from zero; a button already held\n-- when the tag was read counts from its first hold step after the scan.\non("team_input.press", function()\n  if pending then\n    pending.base = 0\n  end\nend)\n\non("team_input.hold", function(e)\n  if not pending then\n    if s.charges > 0 and back == nil then\n      refuse("scan_first")\n    end\n    return\n  end\n  if window then\n    cancel(window)\n    window = nil\n  end\n  if pending.base == nil then\n    pending.base = math.max(0, e.ms - HOLD_STEP_MS)\n  end\n  local progress = (e.ms - pending.base) / (params.heal_hold_s * 1000)\n  if progress >= 1 then\n    heal()\n  else\n    hold_screen(progress)\n  end\nend)\n\non("team_input.release", function()\n  if pending and pending.base ~= nil then\n    refuse("cancelled", { player = pending.player, team = pending.team })\n  end\nend)\n\n-- Mode commands (CMD opcode 8): the controller\'s count of a player\'s heals\n-- at every kit, and the GM\'s refill.\non("cmd.mode", function(e)\n  if e.name == "heals" and type(e.player) == "string" then\n    local n = math.tointeger(e.used) or 0\n    if n > heals_of(e.player) then\n      used[e.player] = n\n    end\n    if type(e.at) == "number" and (last[e.player] == nil or e.at > last[e.player]) then\n      last[e.player] = e.at\n    end\n  elseif e.name == "refill" then\n    s.charges = params.charges\n    log("medic: refilled to " .. s.charges)\n    forget()\n    idle()\n  end\nend)\n',
    'field.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Medic Kit, on the field controller: counts every kit\'s heals per player for\n-- the whole game and tells the kits ("heals" mode command), so a player with a\n-- limit of 2 is not healed twice at every kit. A kit out of reach heals with\n-- its own count; its medic.heal arrives later (the box resends it) and carries\n-- the count the kit knew, so the total here is the larger of the two. A kit\n-- that rebooted is told every count again.\n\nlocal used = {} -- player -> heals in the game, at every kit\nlocal last = {} -- player -> game time (s) the controller heard of their last heal\n\nlocal function tell(node_id, player)\n  field.send(\n    node_id,\n    "mode",\n    { name = "heals", player = player, used = used[player], at = last[player] }\n  )\nend\n\non("medic.heal", function(e)\n  if type(e.player) ~= "string" then\n    return\n  end\n  local n = (used[e.player] or 0) + 1\n  local kit_knew = math.tointeger(e.player_heals_used) or 0\n  if kit_knew > n then\n    n = kit_knew\n  end\n  -- Whole seconds keep the command short (a box takes 127 bytes of parameters).\n  used[e.player], last[e.player] = n, math.floor(game.time())\n  for _, kit in ipairs(field.nodes("medic")) do\n    -- The kit that healed knows its own count unless it was behind.\n    if kit.id ~= e.node or kit_knew < n then\n      tell(kit.id, e.player)\n    end\n  end\nend)\n\non("node.rebooted", function(e)\n  for _, kit in ipairs(field.nodes("medic")) do\n    if kit.id == e.node then\n      for player in pairs(used) do\n        tell(kit.id, player)\n      end\n    end\n  end\nend)\n',
    'assets/screens/medic_empty.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The kit has no heals left until the organisers refill it. Data: team (the\n# team the kit serves, if one). Texts in params.lang (pt or en).\ntemplate: medic_empty\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: LIGADURAS\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: MEDIC KIT\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "0"\n    style: { font_size: 48, color: danger }\n  - type: label\n    text: Sem ligaduras\n    style: { font_size: 28, color: danger, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: The kit is empty\n    style: { font_size: 28, color: danger, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: A organização pode repor o kit\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: The organisers can refill it\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/medic_healed.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A heal is done. Data: player, team (the player\'s), remaining (heals left\n# in the kit), used (the player\'s heals in this game), max (heals a player\n# may have; 0: no limit). Texts in params.lang (pt or en).\ntemplate: medic_healed\nstyle: { background: "{team || \'panel\'}" }\nlayout:\n  - type: icon\n    icon: plus\n    style: { font_size: 48, color: contrast }\n  - type: label\n    text: DE VOLTA AO JOGO\n    style: { font_size: 28, color: contrast, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: BACK IN THE GAME\n    style: { font_size: 28, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: "{player}"\n    style: { font_size: 20, color: contrast }\n  - type: label\n    text: "Tratamento {used} de {max}"\n    style: { font_size: 20, color: contrast, visible: "{params.lang != \'en\' && max > 0}" }\n  - type: label\n    text: "Heal {used} of {max}"\n    style: { font_size: 20, color: contrast, visible: "{params.lang == \'en\' && max > 0}" }\n  - type: label\n    text: "Restam {remaining} ligaduras"\n    style: { font_size: 14, color: contrast, visible: "{params.lang != \'en\' && remaining != 1}", padding: 6 }\n  - type: label\n    text: Resta 1 ligadura\n    style: { font_size: 14, color: contrast, visible: "{params.lang != \'en\' && remaining == 1}", padding: 6 }\n  - type: label\n    text: "{remaining} heals left in the kit"\n    style: { font_size: 14, color: contrast, visible: "{params.lang == \'en\' && remaining != 1}", padding: 6 }\n  - type: label\n    text: 1 heal left in the kit\n    style: { font_size: 14, color: contrast, visible: "{params.lang == \'en\' && remaining == 1}", padding: 6 }\n',
    'assets/screens/medic_hold.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A player\'s tag was read: the heal fills up while the button is held.\n# Data: player, team (the player\'s), progress (0-1), left (seconds still to\n# hold), remaining (heals left in the kit). Texts in params.lang (pt or en).\ntemplate: medic_hold\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: "{player}"\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Mantém premido para tratar\n    style: { font_size: 20, width: 300, align: center, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: Keep holding to heal\n    style: { font_size: 20, width: 300, align: center, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: "{left}"\n    style: { font_size: 48, color: accent }\n  - type: progress_bar\n    value: "{progress}"\n    style: { width: 260, height: 14, color: "{team || \'accent\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Largar antes do tempo cancela\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: Letting go early cancels\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/medic_idle.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The kit waits for a player\'s tag. Data: remaining (heals left), team (the\n# team the kit serves, if one). The texts follow the game\'s params.lang\n# (pt, the default, or en).\ntemplate: medic_idle\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: LIGADURAS\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: MEDIC KIT\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{remaining}"\n    style: { font_size: 48, color: "{remaining <= 1 && \'orange\' || \'white\'}" }\n  - type: label\n    text: "Restam {remaining} ligaduras"\n    style: { font_size: 20, color: muted, visible: "{params.lang != \'en\' && remaining != 1}" }\n  - type: label\n    text: Resta 1 ligadura\n    style: { font_size: 20, color: muted, visible: "{params.lang != \'en\' && remaining == 1}" }\n  - type: label\n    text: "{remaining} heals left"\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'en\' && remaining != 1}" }\n  - type: label\n    text: 1 heal left\n    style: { font_size: 20, color: muted, visible: "{params.lang == \'en\' && remaining == 1}" }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Lê a tua etiqueta\n    style: { font_size: 28, color: accent, visible: "{params.lang != \'en\'}" }\n  - type: label\n    text: Scan your tag\n    style: { font_size: 28, color: accent, visible: "{params.lang == \'en\'}" }\n  - type: label\n    text: e mantém premido o botão\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang != \'en\'}"\n      padding: { bottom: 10 }\n  - type: label\n    text: then hold the button\n    style:\n      font_size: 14\n      color: muted\n      visible: "{params.lang == \'en\'}"\n      padding: { bottom: 10 }\n',
    'assets/screens/medic_refused.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# A tag or a hold was refused. Data: reason (mac, game, no_game, team,\n# not_tag, wrong_team, limit, cooldown, cancelled, scan_first), message (the\n# reason in params.lang, from the script), player and team (when the tag was\n# a player\'s), remaining (heals left in the kit).\ntemplate: medic_refused\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: danger }\n    children:\n      - type: label\n        text: RECUSADO\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang != \'en\'}" }\n      - type: label\n        text: REFUSED\n        style: { font_size: 20, width: fill, align: center, color: contrast, visible: "{params.lang == \'en\'}" }\n  - type: spacer\n    height: fill\n  - type: icon\n    icon: close\n    style: { font_size: 48, color: danger }\n  - type: label\n    text: "{message}"\n    style: { font_size: 20, width: 300, align: center }\n  - type: label\n    text: "{player}"\n    style: { font_size: 20, color: "{team || \'muted\'}", visible: "{player}" }\n  - type: spacer\n    height: fill\n',
  },
  'player_checkin': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.player_checkin\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Player Check-in\ndescription: >-\n  Players check in at a checkpoint by scanning their signed NFC tag. The box counts the players of each\n  team and gives their team points for each check-in. A player counts once, or again after a set time.\n  Forged tags and tags from another game are refused.\nroles:\n  checkpoint: { requires: [nfc], optional: [display] }\nparams:\n  points:         { type: int, min: 0, max: 1000, default: 1, label: "Points for the player\'s team per check-in" }\n  repeat_after_s: { type: int, min: 0, max: 86400, default: 0, label: "Seconds before the same player counts again (0: once per game)" }\ni18n:\n  pt:\n    name: Registo de Presença\n    description: >-\n      Cada participante faz o registo num ponto de controlo lendo a sua etiqueta NFC assinada. A caixa conta\n      as pessoas de cada equipa e dá pontos à equipa por cada registo. Cada pessoa conta uma vez, ou de\n      novo ao fim de um tempo definido. Etiquetas falsificadas ou de outro jogo são recusadas.\n    params:\n      points: Pontos para a equipa por cada registo\n      repeat_after_s: "Segundos até a mesma pessoa voltar a contar (0: uma vez por jogo)"\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Player Check-in: players check in at a checkpoint with their signed NFC\n-- tag (protocol/nfc-tag.md). The box counts check-ins per team and gives the\n-- player\'s team `points` for each. A player counts once per game, or again\n-- after repeat_after_s seconds; a scan before that is a duplicate and is\n-- refused. Forged tags, tags from another game and tags without a team are\n-- refused (the shell checks the signature and says why in nfc.tag\'s reason).\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\n\nlocal seen = {} -- player -> game time of their last check-in that counted\nlocal count = {} -- team -> check-ins\nlocal order = {} -- teams in the order they first checked in\nlocal total = 0\nlocal last_team\nlocal message, failed, fade\n\nlocal function counts()\n  local parts = {}\n  for _, team in ipairs(order) do\n    parts[#parts + 1] = string.upper(team) .. " " .. count[team]\n  end\n  return table.concat(parts, "  ")\nend\n\nlocal function show()\n  ui.screen("checkin", {\n    total = total,\n    counts = counts(),\n    team = last_team,\n    message = message,\n    error = failed,\n  })\nend\n\n-- A message under the counts, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n  end\n  fade = after(4, function()\n    fade = nil\n    message, failed = nil, false\n    show()\n  end)\nend\n\non("game.start", show)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("check-in: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  if e.team == nil then\n    return say("This tag has no team", true)\n  end\n  local t = seen[e.player]\n  if t and (params.repeat_after_s == 0 or game.time() - t < params.repeat_after_s) then\n    return say("Already checked in", true)\n  end\n  seen[e.player] = game.time()\n  if count[e.team] == nil then\n    count[e.team] = 0\n    order[#order + 1] = e.team\n  end\n  count[e.team] = count[e.team] + 1\n  total = total + 1\n  last_team = e.team\n  emit("player.checkin", { team = e.team, player = e.player })\n  score.add(e.team, params.points, "checkin")\n  say("Checked in: " .. e.player, false)\nend)\n',
    'assets/screens/checkin.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The checkpoint. Data: total (check-ins), counts (per team, as text),\n# team (of the last check-in), message, error.\ntemplate: checkin\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: CHECK-IN\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{total}"\n    style: { font_size: 48 }\n  - type: label\n    text: players checked in\n    style: { font_size: 20, color: muted }\n  - type: label\n    text: "{counts}"\n    style: { font_size: 20, visible: "{counts}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Scan your tag to check in\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
  'respawn': {
    'mode.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\nid: org.atalaia.respawn\nversion: 0.1.0\nlicense: GPL-3.0-or-later\nmin_tier: reduced\nkind: mode\nname: Respawn and Lives\ndescription: >-\n  A respawn point counts lives. Players scan their signed NFC tag (or press their team\'s button) to come\n  back into the game; each respawn takes a life from their team, or from the player with per-player\n  lives, and a player must wait a cooldown between respawns. When a team has no lives left, the next\n  respawn is refused and the team is eliminated.\nroles:\n  respawn: { requires: [nfc], optional: [team_input, display] }\nparams:\n  lives:              { type: int, min: 1, max: 1000, default: 20, label: "Lives: respawns per team, or per player with per-player lives" }\n  per_player:         { type: bool, default: false, label: "Count lives per player (needs NFC tags) instead of per team" }\n  respawn_cooldown_s: { type: int, min: 0, max: 600, default: 30, label: "Seconds a player waits between respawns" }\ni18n:\n  pt:\n    name: Reentradas e Vidas\n    description: >-\n      Um ponto de reentrada conta as vidas. Cada participante lê a sua etiqueta NFC assinada (ou carrega no\n      botão da sua equipa) para voltar ao jogo; cada reentrada gasta uma vida da equipa, ou da própria\n      pessoa com vidas individuais, e há um tempo de espera entre reentradas. Quando uma equipa fica sem\n      vidas, a reentrada seguinte é recusada e a equipa é eliminada.\n    params:\n      lives: "Vidas: reentradas por equipa, ou por pessoa com vidas individuais"\n      per_player: Contar as vidas por pessoa (precisa de etiquetas NFC) em vez de por equipa\n      respawn_cooldown_s: Segundos de espera entre reentradas de cada pessoa\n',
    'node.lua':
        '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n-- SPDX-License-Identifier: GPL-3.0-or-later\n--\n-- Respawn and Lives: a respawn point counts lives. A player scans their\n-- signed NFC tag (protocol/nfc-tag.md), or presses their team\'s button, to\n-- come back into the game. Each respawn takes one of the team\'s `lives`, or\n-- one of the player\'s own with per_player. A player waits respawn_cooldown_s\n-- between respawns; button presses carry no player, so they only have a 2 s\n-- guard against double presses. When a team has no lives left, the next\n-- respawn is refused and team.eliminated is sent (once). Lives are counted on\n-- this box: give each team one respawn point, or share one.\n\nlocal refused = {\n  unsigned = "Not a game tag",\n  no_game = "No game: join one first",\n  game = "Tag from another game",\n  mac = "Forged tag",\n  team = "Unknown team",\n  format = "Damaged tag",\n  version = "Unknown tag version",\n}\nlocal BUTTON_GUARD_S = 2\n\nlocal lives = {} -- team, or player with per_player -> lives left\nlocal last = {} -- player id, or "team:<team>" for buttons -> game time of the last respawn\nlocal out = {} -- team -> true once team.eliminated was sent\nlocal message, failed, fade\nlocal shown = { lives = params.lives }\n\nlocal function show()\n  ui.screen("respawn", {\n    team = shown.team,\n    player = shown.player,\n    lives = shown.lives,\n    message = message,\n    error = failed,\n  })\nend\n\n-- A message under the lives count, cleared after 4 s.\nlocal function say(text, bad)\n  message, failed = text, bad\n  show()\n  if fade then\n    cancel(fade)\n  end\n  fade = after(4, function()\n    fade = nil\n    message, failed = nil, false\n    show()\n  end)\nend\n\nlocal function lives_of(key)\n  if lives[key] == nil then\n    lives[key] = params.lives\n  end\n  return lives[key]\nend\n\nlocal function respawn(team, player)\n  if params.per_player and player == nil then\n    return say("Scan your tag", true)\n  end\n  if team == nil and not params.per_player then\n    return say("This tag has no team", true)\n  end\n  local who = player or ("team:" .. team)\n  local wait_s = player and params.respawn_cooldown_s or BUTTON_GUARD_S\n  local t = last[who]\n  if t and game.time() - t < wait_s then\n    return say("Wait " .. math.ceil(wait_s - (game.time() - t)) .. " s", true)\n  end\n  local key = params.per_player and player or team\n  shown.team, shown.player = team, player\n  shown.lives = lives_of(key)\n  if lives_of(key) <= 0 then\n    if not params.per_player and not out[team] then\n      out[team] = true\n      emit("team.eliminated", { team = team })\n    end\n    return say(params.per_player and "No lives left" or "No lives left: team out", true)\n  end\n  lives[key] = lives[key] - 1\n  last[who] = game.time()\n  shown.lives = lives[key]\n  emit("player.respawn", { team = team, player = player, lives_left = lives[key] })\n  say("Back in the game", false)\nend\n\non("game.start", show)\n\non("nfc.tag", function(e)\n  if not e.valid then\n    log("respawn: tag " .. tostring(e.uid) .. " refused: " .. tostring(e.reason))\n    return say(refused[e.reason] or "Not a game tag", true)\n  end\n  respawn(e.team, e.player)\nend)\n\non("team_input.press", function(e)\n  respawn(e.team, nil)\nend)\n',
    'assets/screens/respawn.yaml':
        '# SPDX-FileCopyrightText: 2026 The Atalaia contributors\n# SPDX-License-Identifier: GPL-3.0-or-later\n#\n# The respawn point. Data: lives (left, for the last team or player),\n# team, player (the last respawn), message, error.\ntemplate: respawn\nlayout:\n  - type: row\n    style: { width: fill, height: 44, background: "{team || \'panel\'}" }\n    children:\n      - type: label\n        text: RESPAWN\n        style: { font_size: 20, width: fill, align: center, color: contrast }\n  - type: spacer\n    height: fill\n  - type: label\n    text: "{lives}"\n    style: { font_size: 48, color: "{lives == 0 && \'danger\' || \'white\'}" }\n  - type: label\n    text: lives left\n    style: { font_size: 20, color: muted, visible: "{!team && !player}" }\n  - type: label\n    text: "lives left for {team|upper}"\n    style: { font_size: 20, color: team, visible: "{team && !params.per_player}" }\n  - type: label\n    text: "lives left for {player}"\n    style: { font_size: 20, color: muted, visible: "{player && params.per_player}" }\n  - type: label\n    text: "{message}"\n    style:\n      font_size: 20\n      width: 300\n      color: "{error && \'danger\' || \'accent\'}"\n      visible: "{message}"\n      padding: { top: 6 }\n  - type: spacer\n    height: fill\n  - type: label\n    text: Scan your tag to come back in\n    style:\n      font_size: 14\n      color: muted\n      padding: { bottom: 10 }\n',
  },
};
